import {createServer} from 'node:http';import {createRequire} from 'node:module';import {appendFileSync} from 'node:fs';import {join,resolve} from 'node:path';
const [base,out]=process.argv.slice(2),{WebSocketServer}=createRequire(join(resolve(base),'package.json'))('ws');const log=x=>appendFileSync(out,JSON.stringify({time:Date.now(),...x})+'\n');const server=createServer((req,res)=>{res.writeHead(req.url==='/health'?200:404);res.end('{}')});const wss=new WebSocketServer({server});
wss.on('connection',ws=>{ws.on('pong',()=>log({pong:true}));ws.on('message',data=>{const f=JSON.parse(String(data));log({in:f});const send=o=>{if(ws.readyState===ws.OPEN){log({out:o});ws.send(JSON.stringify(o))}};if(f.type==='hello')send({type:'hello_ok',protocolVersion:'1.2',serverVersion:'fixture',serverInfo:{capabilities:[]}});else if(f.method==='list_sessions')send({type:'response',id:f.id,ok:true,result:{sessions:[]}});else if(f.method==='submit_turn'){setTimeout(()=>{if(ws.readyState===ws.OPEN){log({ping:true});ws.ping('probe');send({type:'event',id:f.id,final:false,event:{type:'assistant_text_delta',text:'FLOW_MARKER'}});}},400);setTimeout(()=>{send({type:'event',id:f.id,final:false,event:{type:'turn_completed'}});send({type:'event',id:f.id,final:true});},800);}else send({type:'response',id:f.id,ok:true,result:{}});});ws.on('close',()=>log({ws_closed:true}));});await new Promise(r=>server.listen(0,'127.0.0.1',r));console.log(server.address().port);process.on('SIGTERM',()=>{for(const ws of wss.clients)ws.terminate();wss.close(()=>server.close(()=>process.exit(0)));setTimeout(()=>process.exit(2),1000).unref()});
